function draw(){
	background('#f4f1de')
	let addon=0
	for(let x=60; x<360; x+=5){
		for(let y=60; y<360; y+=10){
			noStroke()
			fill(colorMixer(seed+0.01, addon, (x+2)/400, colors))
			rect(x, y, 5,5)
